import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"性能策略","description":"","frontmatter":{},"headers":[],"relativePath":"zh/benchmarks.md","filePath":"zh/benchmarks.md","lastUpdated":1785222314000}`),a={name:`zh/benchmarks.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="性能策略" tabindex="-1">性能策略 <a class="header-anchor" href="#性能策略" aria-label="Permalink to “性能策略”">​</a></h1><p>性能证据必须来自优化后的 native binding。Debug binding 适合开发和正确性检查，但不能 作为发布性能信号。</p><h2 id="发布门禁" tabindex="-1">发布门禁 <a class="header-anchor" href="#发布门禁" aria-label="Permalink to “发布门禁”">​</a></h2><p><code>pnpm run bench:report</code> 会先用 Cargo release profile 构建 native binding，再连续运行 三轮 Vitest benchmark，并把中位数报告写入 <code>benchmarks/current.json</code>。CI benchmark 任务固定 Ubuntu 24.04、Node.js 24 和仓库 Rust 工具链，使软件环境保持可比。</p><p>代表性兼容场景会在每一轮中，用同一份 Roboto 输入和 <code>glyph + ttf2woff</code> 请求分别运行 fontmin-rs 与经典 Fontmin。当 fontmin-rs 的配对平均耗时比例超过 1.10 时，发布门禁会 失败。同一进程内的配对比例比绝对毫秒阈值更不容易受到 hosted runner 硬件波动影响。</p><p>已提交的 <a href="../../benchmarks/baseline.json"><code>benchmarks/baseline.json</code></a> 会记录机器指纹、 fixture checksum、三轮独立均值、中位数指标和性能判定。只能通过以下命令重录：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench:baseline</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>提交新基线前必须审查完整 diff。性能变慢时，需要再进行三轮同环境复测，并修复问题或 记录有意保留的正确性取舍。</p><h2 id="当前结果" tabindex="-1">当前结果 <a class="header-anchor" href="#当前结果" aria-label="Permalink to “当前结果”">​</a></h2><p>Release profile 基线中，代表性 fontmin-rs pipeline 的平均耗时比例为经典 Fontmin 的 0.1485，约快 6.73 倍。此前 debug profile 快照造成的落后结论并非产品回退；改用 release profile 门禁后，该测量错误已经消除。</p><p>Subset、WOFF、WOFF2、SVG 和 modern-web pipeline 的绝对耗时仍保留在报告中用于诊断。 由于不同任务间的 CPU 配额可能变化，hosted runner 的绝对耗时只作为证据，不设为硬门禁。</p><p>运行 <code>pnpm run bench:profile</code> 可对代表性 pipeline 进行粗粒度 CPU profile。它会执行 2,500 次 release binding，并在 <code>benchmarks/</code> 下写入被忽略的 <code>.cpuprofile</code>。 beta.3 profile 表明 glyph subsetting 是最大的具名耗时块，JavaScript pipeline 调度并非主要热点。由于配对门禁已经明显优于 parity，beta.3 不需要记录任何以正确性换取 性能的取舍。</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};